  other: { sessionID: "<ses_1>", directory: "sub" },
  missingDir: { directory: "does/not/exist" },
  file: { directory: "README.md" },
  missingSession: { sessionID: "ses_doesnotexist", directory: "sub" },
  empty: { directory: "" },
}) ) {
